sealed interface HomeUiState {
    data object Loading : HomeUiState
    data class Success(val categories: List<Category>) : HomeUiState
    data class Error(val message: String) : HomeUiState
}

// compiler forces you to handle every branch - no 'else' needed or wanted
when (val state = uiState) {
    is HomeUiState.Loading -> ShowSpinner()
    is HomeUiState.Success -> ShowList(state.categories)
    is HomeUiState.Error -> ShowError(state.message)
}

sealed class AppError {
    data class Network(val code: Int) : AppError()
    data object Auth : AppError()
    data class Validation(val field: String) : AppError()
}

sealed class Result<out T> {
    data class Success<T>(val data: T) : Result<T>()
    data class Failure(val error: AppError) : Result<Nothing>()
}

when (val result = repository.login(email, password)) {
    is Result.Success -> navigateHome()
    is Result.Failure -> when (result.error) {
        is AppError.Auth -> showInvalidCredentials()
        is AppError.Network -> showRetryDialog()
        is AppError.Validation -> highlightField(result.error.field)
    }
}
